 "content": "from collections import Counter


def transform(grid):
    """Extend left-anchored horizontal bands by marking their background tails."""
    out = [row[:] for row in grid]
    background = Counter(value for row in grid for value in row).most_common(1)[0][0]
    for r, row in enumerate(grid):
        if not row or row[0] == background:
            continue
        band = row[0]
        c = 1
        while c < len(row) and row[c] == band:
            c += 1
        if c < len(row) and all(value == background for value in row[c:]):
            for j in range(c, len(row)):
                out[r][j] = 1
    return out


